const pastas = $input.all().filter(i => i.json && i.json.folder);
// OneDrive/Graph: pasta é o item que tem o campo "folder".
// OK = entregue; EXE = em processamento por outra execução: ambas são ignoradas.
const pend = pastas.filter(i => !/^\s*(OK|EXE)\b/i.test(i.json.name || ''));
pend.sort((a, b) => new Date(a.json.createdDateTime || 0) - new Date(b.json.createdDateTime || 0));
return pend.length ? pend : [{ json: { raizApenas: true } }];

const sub = $input.all().map(i => i.json);
// mapa id da pasta -> nome e data (vem do Filtrar subpastas, já sem OK/EXE)
const pastas = {}, criado = {};
for (const it of $('Filtrar subpastas').all().map(i => i.json)) {
  if (it && it.id && it.name) { pastas[it.id] = it.name; criado[it.id] = it.createdDateTime || ''; }
}
const grupos = {}, ultimaMod = {};
for (const f of sub) {
  if (!f || !f.id || !f.name) continue;
  if (f.folder) continue; // subpasta aninhada não entra como arquivo
  const nome = f.name;
  if (!nome.toLowerCase().endsWith('.docx')) continue;
  if (nome.includes('(Águia') || nome.includes('(Aguia')) continue;
  const pai = (f.parentReference && f.parentReference.id) || null;
  const nomePasta = pai ? pastas[pai] : null;
  if (!nomePasta) continue;
  const mod = new Date(f.lastModifiedDateTime || 0).getTime();
  if (!ultimaMod[pai] || mod > ultimaMod[pai]) ultimaMod[pai] = mod;
  const mOrd = nome.match(/^(\d+(?:\.\d+)*)/);
  const grupo = 'pasta:' + pai;
  const ordem = mOrd ? mOrd[1] : '999';
  const mp = nomePasta.match(/^(\d+)/);
  const prefixo = mp ? mp[1] : nomePasta.replace(/[^\w\d]+/g, ' ').trim();
  const ehQuestoes = /QUEST/i.test(nome) && !/TEORIA/i.test(nome);
  if (!grupos[grupo]) grupos[grupo] = [];
  grupos[grupo].push({ id: f.id, nome, ordem, prefixo, tipo: ehQuestoes ? 'questoes' : 'material', pasta: pai });
}
const chave = o => String(o).split('.').map(Number);
const cmp = (a, b) => {
  const A = chave(a.ordem), B = chave(b.ordem);
  for (let i = 0; i < Math.max(A.length, B.length); i++) {
    const d = (A[i] || 0) - (B[i] || 0);
    if (d) return d;
  }
  return a.tipo === 'material' ? -1 : 1;
};
const ASSENTAMENTO_MS = 3 * 60 * 1000; // pasta só roda 3 min após o último upload
const agora = Date.now();
const saida = [];
for (const arquivos of Object.values(grupos)) {
  const materiais = arquivos.filter(a => a.tipo === 'material').sort(cmp);
  const questoes = arquivos.filter(a => a.tipo === 'questoes').sort(cmp);
  if (!materiais.length || !questoes.length) continue;
  const pai = materiais[0].pasta;
  if (ultimaMod[pai] && (agora - ultimaMod[pai]) < ASSENTAMENTO_MS) continue; // upload ainda em andamento
  saida.push({ json: { prefixo: materiais[0].prefixo, pastaDestino: pai, nomePasta: pastas[pai] || null, criadoEm: criado[pai] || '', arquivos: [...materiais, ...questoes] } });
}
saida.sort((a, b) => new Date(a.json.criadoEm || 0) - new Date(b.json.criadoEm || 0));
return saida;

const metas = $('Explodir arquivos do grupo').all();
const resp = $input.all();
if (metas.length !== resp.length) throw new Error(`Extração incompleta: ${resp.length} de ${metas.length} arquivos`);
const material = [], questoes = [];
const imagens = {};
let prox = 1;
for (let i = 0; i < resp.length; i++) {
  const meta = metas[i].json;
  let texto = resp[i].json.text || '';
  const imgs = resp[i].json.images || [];
  const mapa = {};
  for (const im of imgs) {
    mapa[im.n] = prox;
    imagens[String(prox)] = { base64: im.base64, mime: im.mime };
    prox++;
  }
  texto = texto.replace(/\[IMAGEM (\d+)\]/g, (mm, n) => mapa[n] ? `[IMAGEM ${mapa[n]}]` : '');
  const bloco = `\n\n===== PARTE ${meta.ordem} (${meta.nome}) =====\n${texto}`;
  if (meta.tipo === 'material') material.push(bloco); else questoes.push(bloco);
}
return [{ json: {
  prefixo: $('Processar um par').first().json.prefixo,
  nomePasta: $('Processar um par').first().json.nomePasta || null,
  nomesArquivos: metas.map(m => m.json.nome),
  materialTexto: material.join('\n'),
  questoesTexto: questoes.join('\n'),
  imagens
} }];

function textoGemini(j) {
  const c = (j.candidates && j.candidates[0]) || {};
  const parts = (c.content && c.content.parts) || [];
  return parts.map(p => p.text || '').join('').trim();
}
const complemento = textoGemini($input.first().json);
if (!complemento) throw new Error('Pesquisa Gemini voltou vazia');
const j = $('Juntar textos').first().json;
const prompt = ['Você é o revisor técnico de material de concurso. Abaixo estão (1) o material bruto original e (2) um COMPLEMENTO gerado por pesquisa. Sua tarefa: verificar o COMPLEMENTO com pesquisa na web (Google Search) e devolver a versão final corrigida.',
'',
'PROTOCOLO DE VERIFICAÇÃO (obrigatório):',
'1. Toda afirmação VERIFICÁVEL do complemento (número de lei, artigo, parágrafo, súmula, tese, data, percentual, prazo, nome de órgão, definição técnica, fórmula, gabarito de regra) deve ser CONFIRMADA por busca no Google antes de ser mantida. Não aprove por plausibilidade: confira na fonte.',
'2. Achou erro? CORRIJA no lugar, substituindo pela versão correta do mesmo ponto (não deixe buraco). Remoção pura só para afirmação falsa sem correção possível.',
'3. CONFLITO com o material original: se o complemento contradisser o material original, prevalece o que a busca confirmar na fonte oficial. Se o complemento estiver errado, corrija-o. Se o original é que estiver desatualizado ou errado, mantenha no complemento a versão correta confirmada, deixando-a claramente afirmada (sem mencionar que há divergência com o material).',
'4. BANCAS: se o complemento citar nome de banca examinadora (FGV, CEBRASPE, CESPE, FCC, Vunesp, Quadrix, Cesgranrio, AOCP, IBFC ou qualquer outra) ou concurso específico com órgão e ano, SUBSTITUA por referência genérica ("a banca", "as provas", "os examinadores"), mantendo o conteúdo da frase. O texto final não pode conter nome de banca.',
'5. Não acrescente assunto novo que não esteja no complemento.',
'',
'PROIBIDO RESUMIR: fora as correções do protocolo, o texto final deve ter praticamente o MESMO TAMANHO do complemento recebido (ou maior, se uma correção exigir explicação). Devolver versão encurtada é erro grave. Mantenha todas as seções, exemplos e desenvolvimentos que passarem na verificação.',
'Mantenha o mesmo padrão de linguagem do primeiro ao último parágrafo, sem rebuscar nas seções finais. Mantenha os **negritos** existentes. Travessão (—) é PROIBIDO: use dois pontos, vírgula ou ponto.',
'Responda SOMENTE com a versão final corrigida do complemento, sem preâmbulo, sem relatório da revisão, sem comentários.',
'',
'<<<MATERIAL_ORIGINAL',
j.materialTexto || '',
'MATERIAL_ORIGINAL>>>',
'',
'<<<COMPLEMENTO',
complemento,
'COMPLEMENTO>>>'].join('\n');
const body = {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  tools: [{ google_search: {} }],
  generationConfig: { maxOutputTokens: 65536 }
};
return [{ json: { prefixo: j.prefixo, complementoBruto: complemento, bodyString: JSON.stringify(body) } }];

function textoGemini(j) {
  const c = (j.candidates && j.candidates[0]) || {};
  const parts = (c.content && c.content.parts) || [];
  return parts.map(p => p.text || '').join('').trim();
}
let complemento = textoGemini($input.first().json);
if (!complemento) complemento = $('Montar verificação Gemini').first().json.complementoBruto || '';
complemento = complemento.replace(/\u2014/g, ':');
const j = $('Juntar textos').first().json;
const materialTexto = (j.materialTexto || '') +
  '\n\n===== COMPLEMENTO DE PESQUISA VERIFICADO (Gemini) =====\n' + complemento;
return [{ json: {
  prefixo: j.prefixo,
  materialTexto,
  questoesTexto: j.questoesTexto || '',
  tamanhoOriginal: (j.materialTexto || '').length,
  tamanhoComplemento: complemento.length
} }];

function sanearEstrutura(s) {
  // descarta } ou ] espúrios (fechamento a mais no meio do JSON), fora de strings
  let out = '', stack = [], inStr = false, esc = false;
  for (let idx = 0; idx < s.length; idx++) {
    const ch = s[idx];
    if (inStr) { out += ch; if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') { inStr = true; out += ch; continue; }
    if (ch === '{' || ch === '[') { stack.push(ch); out += ch; continue; }
    if (ch === '}' || ch === ']') {
      const esperado = ch === '}' ? '{' : '[';
      if (stack.length && stack[stack.length - 1] === esperado) { stack.pop(); out += ch; }
      continue;
    }
    out += ch;
  }
  return out;
}
function stripTrailingCommas(s) {
  let out = '', inStr = false, esc = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (inStr) { out += ch; if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') { inStr = true; out += ch; continue; }
    if (ch === ',') { let j = i + 1; while (j < s.length && /\s/.test(s[j])) j++; if (s[j] === ']' || s[j] === '}') continue; }
    out += ch;
  }
  return out;
}
function repararJson(s) {
  let stack = [], inStr = false, esc = false;
  for (const ch of s) {
    if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') inStr = true;
    else if (ch === '{' || ch === '[') stack.push(ch);
    else if (ch === '}' || ch === ']') { if (stack.length) stack.pop(); }
  }
  if (inStr) s += '"';
  for (let i = stack.length - 1; i >= 0; i--) s += stack[i] === '{' ? '}' : ']';
  return s;
}
function parseResiliente(fatia) {
  const tentativas = [
    x => x,
    x => stripTrailingCommas(x),
    x => sanearEstrutura(x),
    x => stripTrailingCommas(sanearEstrutura(x)),
    x => stripTrailingCommas(repararJson(sanearEstrutura(x))),
    x => stripTrailingCommas(repararJson(x)),
  ];
  let err;
  for (const t of tentativas) {
    try { return JSON.parse(t(fatia)); } catch (e) { if (!err) err = e; }
  }
  throw new Error('JSON da IA irrecuperável: ' + err.message);
}

function extrairJson(j) {
  let s = j.merged || j.merged_response || (Array.isArray(j.content) ? j.content.filter(c => c.type === 'text').map(c => c.text).join('\n') : '') || j.text || '';
  s = s.trim();
  if (s.startsWith('```')) {
    s = s.replace(/^```(?:json)?\s*/, '').replace(/```\s*$/, '');
  }
  s = s.replace(/"text"\s*:/g, '"texto":');
  const i = s.indexOf('{');
  const f = s.lastIndexOf('}');
  if (i === -1 || f === -1) throw new Error('Resposta da IA sem JSON');
  return parseResiliente(s.slice(i, f + 1));
}

function separaCabecalho(cab) {
  cab = String(cab || '');
  if (!/^\s*\d+\s*\.\s*\(/.test(cab)) return null;
  const abre = cab.indexOf('(');
  let depth = 0;
  for (let k = abre; k < cab.length; k++) {
    if (cab[k] === '(') depth++;
    else if (cab[k] === ')') {
      depth--;
      if (depth === 0) {
        return { cabecalho: cab.slice(0, k + 1), resto: cab.slice(k + 1).trim() };
      }
    }
  }
  return null;
}

const teoria = extrairJson($('Gerar conteúdo estruturado').first().json);
const quest = extrairJson($input.first().json);

let questoesArr = Array.isArray(quest.questoes) ? quest.questoes : [];
let comentariosArr = Array.isArray(quest.comentarios) ? quest.comentarios : [];
let gabaritoArr = Array.isArray(quest.gabarito) ? quest.gabarito : [];

for (const c of comentariosArr) {
  if (c && Array.isArray(c.gabarito)) {
    if (!gabaritoArr.length) gabaritoArr = c.gabarito;
    c.gabarito = '';
  }
}
comentariosArr = comentariosArr.filter(c => c && (
  (c.cabecalho && String(c.cabecalho).trim()) ||
  (c.comentario && String(c.comentario).trim()) ||
  (Array.isArray(c.corpo) && c.corpo.some(x => String(x || '').trim()))
));

questoesArr = questoesArr.map(q => {
  if (!q) return q;
  const corpoUtil = Array.isArray(q.corpo) ? q.corpo.filter(x => String(x || '').trim()) : [];
  if (!corpoUtil.length) {
    const sep = separaCabecalho(q.cabecalho);
    if (sep && sep.resto) {
      q = Object.assign({}, q, { cabecalho: sep.cabecalho, corpo: [sep.resto] });
      return q;
    }
  }
  q.corpo = corpoUtil.length ? corpoUtil : (Array.isArray(q.corpo) ? q.corpo : []);
  return q;
});

const dados = {
  titulo: teoria.titulo || 'Material',
  apresentacao: teoria.apresentacao || [],
  capitulos: teoria.capitulos || [],
  questoes: questoesArr,
  comentarios: comentariosArr,
  gabarito: gabaritoArr
};

dados.comentarios = dados.comentarios.map((c, i) => {
  const q = dados.questoes[i] || {};
  let g = c.gabarito;
  if (g == null || Array.isArray(g)) g = '';
  let corpo = (Array.isArray(c.corpo) && c.corpo.some(x => String(x || '').trim())) ? c.corpo : (Array.isArray(q.corpo) ? q.corpo : []);
  if (!corpo.some(x => String(x || '').trim())) {
    const sep = separaCabecalho(c.cabecalho);
    if (sep && sep.resto) corpo = [sep.resto];
  }
  return {
    cabecalho: c.cabecalho || q.cabecalho || '',
    corpo: corpo,
    gabarito: String(g),
    comentario: c.comentario || ''
  };
});

if (gabaritoArr.length < dados.questoes.length) {
  for (let i = 0; i < dados.questoes.length; i++) {
    if (!gabaritoArr[i]) {
      const g = String((dados.comentarios[i] || {}).gabarito || '').trim();
      const m = /^letra\s*([a-e])$/i.exec(g);
      gabaritoArr[i] = { n: i + 1, g: m ? m[1].toUpperCase() : g };
    }
  }
  dados.gabarito = gabaritoArr;
}
dados.comentarios = dados.comentarios.map((c, i) => {
  if (!c.gabarito && dados.gabarito[i] && dados.gabarito[i].g) {
    const g = String(dados.gabarito[i].g);
    c.gabarito = /^[A-E]$/.test(g) ? ('Letra ' + g) : g;
  }
  return c;
});

dados.imagens = $('Juntar textos').first().json.imagens || {};
const prefixo = $('Processar um par').first().json.prefixo;
const titulo = (dados.titulo || 'Material').replace(/[\\/:*?"<>|]/g, '');
const filename = `Aula ${prefixo} - ${titulo} (Águia Deep).docx`;

const payload = {
  data: dados,
  filename: filename,
  paginate: true
};

return [{ json: { prefixo, filename, payloadString: JSON.stringify(payload) } }];

// vários arquivos novos no mesmo minuto = vários itens do trigger;
